#!/usr/bin/env node
// Guardrail audit for C# projects generated by a TypeScript -> C# migration.
//
// Usage: node audit-csharp-projects.mjs [repo-root] [--strict]
//
// Checks layout, central package management, MSTest-only testing, analyzer policy and the
// repository's naming rules WITHOUT building. Exit code 1 means at least one FAIL.
//
// Defaults match the NuGet Package Manager repository; change the constants below for another
// product. WARN findings are advisory; --strict turns the one-type-per-file check into a FAIL.
import fs from "node:fs";
import path from "node:path";

const root = path.resolve(process.argv[2] ?? ".");
const strict = process.argv.includes("--strict");

const FORBIDDEN_PACKAGES = [
  "xunit",
  "xunit.core",
  "nunit",
  "nunit3testadapter",
  "mediatr",
  "specflow",
  "swashbuckle",
  "serilog",
  "fluentvalidation",
  "polly",
];

const findings = [];
const add = (severity, file, message) => findings.push({ severity, file, message });
const fail = (file, message) => add("FAIL", file, message);
const warn = (file, message) => add("WARN", file, message);

const read = (file) => fs.readFileSync(file, "utf8");
const rel = (file) => path.relative(root, file).replaceAll("\\", "/");
const exists = (file) => fs.existsSync(file);
const walk = (dir, match, out = []) => {
  if (!exists(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (["node_modules", "bin", "obj", ".git"].includes(entry.name)) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, match, out);
    else if (match(entry.name)) out.push(full);
  }
  return out;
};

// ---------------------------------------------------------------- root policy
const buildProps = path.join(root, "Directory.Build.props");
if (!exists(buildProps)) {
  fail("Directory.Build.props", "missing root build policy");
} else {
  const text = read(buildProps);
  for (const token of [
    "TreatWarningsAsErrors",
    "EnforceCodeStyleInBuild",
    "AnalysisLevel",
    "EnableNETAnalyzers",
    "<Nullable>enable</Nullable>",
    "<RollForward>",
    "GenerateDocumentationFile",
    "Fixtures",
  ]) {
    if (!text.includes(token)) fail("Directory.Build.props", `missing '${token}'`);
  }
}

const packagesProps = path.join(root, "Directory.Packages.props");
if (!exists(packagesProps)) {
  fail("Directory.Packages.props", "missing central package versions");
} else {
  const text = read(packagesProps);
  if (!/<ManagePackageVersionsCentrally[^>]*>true</.test(text)) {
    fail("Directory.Packages.props", "central package management is not enabled");
  }
  for (const pkg of ["MSTest.TestFramework", "MSTest.TestAdapter", "Moq", "coverlet.collector"]) {
    if (!text.includes(pkg)) warn("Directory.Packages.props", `no central version for ${pkg}`);
  }
  const lowered = text.toLowerCase();
  for (const pkg of FORBIDDEN_PACKAGES) {
    if (new RegExp(`Include="${pkg}"`, "i").test(lowered)) {
      fail("Directory.Packages.props", `forbidden package centrally versioned: ${pkg}`);
    }
  }
}

// ---------------------------------------------------------------- projects
const sourceProjects = walk(path.join(root, "src"), (n) => n.endsWith(".csproj"));
const testProjects = walk(path.join(root, "tests"), (n) => n.endsWith(".csproj"));
const slnx = fs
  .readdirSync(root)
  .filter((n) => n.endsWith(".slnx") || n.endsWith(".sln"))
  .map((n) => path.join(root, n))[0];

const slnxText = slnx ? read(slnx).replaceAll("\\", "/").toLowerCase() : "";
if (!slnx) fail(".", "no .slnx/.sln at the repository root");

for (const project of [...sourceProjects, ...testProjects]) {
  const file = rel(project);
  const text = read(project);
  const isFixture = file.includes("/Fixtures/");
  if (isFixture) continue; // test data, not part of the solution

  if (!/<TargetFramework>/.test(text)) fail(file, "no TargetFramework");

  if (/<PackageReference[^>]*\bVersion\s*=/.test(text)) {
    fail(file, "PackageReference carries a Version; move it to Directory.Packages.props");
  }
  for (const pkg of FORBIDDEN_PACKAGES) {
    if (new RegExp(`<PackageReference[^>]*Include="${pkg}"`, "i").test(text)) {
      fail(file, `forbidden package reference: ${pkg}`);
    }
  }
  if (/<TreatWarningsAsErrors>|<AnalysisLevel>|<Nullable>/.test(text)) {
    warn(file, "duplicates root policy; remove it so the policy has one home");
  }

  const isExe = /<OutputType>Exe<\/OutputType>/.test(text);
  if (isExe && !/<UseAppHost>false<\/UseAppHost>/.test(text)) {
    fail(file, "sidecar exe must set UseAppHost=false (framework-dependent)");
  }
  if (isExe && /PublishTrimmed|PublishReadyToRun/.test(text)) {
    fail(file, "trimming/R2R measured as a loss for the sidecar; remove it");
  }

  if (slnx && !slnxText.includes(file.toLowerCase())) {
    warn(file, "not registered in the solution file (built only transitively)");
  }
}

for (const test of testProjects) {
  const file = rel(test);
  if (file.includes("/Fixtures/")) continue;
  const text = read(test);
  const name = path.basename(test);
  const looksLikeTests = name.endsWith(".Tests.csproj");
  if (!looksLikeTests) continue; // TestUtilities and similar are support projects

  if (!/<IsTestProject>true<\/IsTestProject>/.test(text)) fail(file, "missing IsTestProject=true");
  if (!/<IsPackable>false<\/IsPackable>/.test(text)) fail(file, "missing IsPackable=false");
  if (!text.includes("MSTest.TestFramework")) fail(file, "does not reference MSTest.TestFramework");
}

// one test project per source project (advisory: primitives/constants may have none)
for (const project of sourceProjects) {
  const dir = path.dirname(project);
  const name = path.basename(dir);
  if (name.endsWith(".Common") || name.endsWith(".TestUtilities")) continue;
  const expected = path.join(root, "tests", `${name}.Tests`);
  if (!exists(expected)) warn(rel(project), `no matching test project tests/${name}.Tests`);
}

// ---------------------------------------------------------------- source files
const typeDecl = /^(?:public|internal|sealed|abstract|static|partial|file)?\s*(?:sealed\s+|abstract\s+|static\s+|partial\s+)*(class|record|struct|interface|enum)\s+\w+/gm;
const asyncMethod = /\basync\s+(?:override\s+)?(?:Task|ValueTask|IAsyncEnumerable)\b[^(]*?\b([A-Za-z_]\w*)\s*\(/g;
const dtoType = /\b(?:class|record|struct|interface)\s+(\w*Dto)\b/;

for (const file of walk(path.join(root, "src"), (n) => n.endsWith(".cs"))) {
  const relative = rel(file);
  if (relative.includes("/obj/") || relative.includes("/bin/")) continue;
  const text = read(file);

  for (const match of text.matchAll(asyncMethod)) {
    const method = match[1];
    if (method === "Main" || method.endsWith("Async")) continue;
    fail(relative, `async method '${method}' does not end with Async`);
  }

  const dto = text.match(dtoType);
  if (dto) fail(relative, `type '${dto[1]}' uses the banned Dto suffix`);

  const types = [...text.matchAll(typeDecl)];
  if (types.length > 1) {
    const message = `${types.length} top-level types in one file (${types
      .map((m) => m[0].split(/\s+/).at(-1))
      .join(", ")})`;
    if (strict) fail(relative, message);
    else warn(relative, message);
  }
}

// ---------------------------------------------------------------- test files
const testFiles = walk(path.join(root, "tests"), (n) => n.endsWith(".cs"));
for (const file of testFiles) {
  const relative = rel(file);
  if (relative.includes("/obj/") || relative.includes("/bin/") || relative.includes("/Fixtures/")) continue;
  const text = read(file);
  if (!/\[TestClass\]/.test(text)) continue; // helpers and utilities

  if (!/^\s*\/\/ File: /m.test(text.split(/\r?\n/).slice(0, 3).join("\n"))) {
    fail(relative, "missing '// File:' header in the first three lines");
  }
  if (!/\[TestCategory\(/.test(text)) fail(relative, "no [TestCategory(...)] on any test");

  const methods = [...text.matchAll(/\[TestMethod\][\s\S]{0,200}?(?:public|internal)\s+(?:async\s+)?[\w<>\[\], ?.]+\s+(\w+)\s*\(/g)];
  for (const match of methods) {
    if (!match[1].includes("_")) {
      fail(relative, `test method '${match[1]}' does not follow Method_Scenario_ExpectedResult`);
    }
  }
}

// ---------------------------------------------------------------- report
const failures = findings.filter((f) => f.severity === "FAIL");
const warnings = findings.filter((f) => f.severity === "WARN");

for (const finding of [...failures, ...warnings]) {
  console.log(`${finding.severity.padEnd(4)} ${finding.file}: ${finding.message}`);
}

console.log(
  `\n${sourceProjects.length} source projects, ${testProjects.length} projects under tests/, ` +
    `${failures.length} failure(s), ${warnings.length} warning(s).`
);
if (failures.length > 0) {
  console.log("Fix failures before the first build; a generated project that fails this audit fails review.");
}
process.exit(failures.length === 0 ? 0 : 1);
